<?php

use Symfony\Component\Finder\Finder;

/**
 * Unescaped Blade output ({!! !!}) is only safe for HTML that is sanitized before it is
 * stored (see App\Casts\SanitizedHtml) or generated by trusted code. Every use must be
 * reviewed and listed here; anything else should use {{ }}.
 *
 * @var list<string>
 */
const REVIEWED_UNESCAPED_OUTPUT = [
    'components/section-display.blade.php: {!! $model->text !!}',
    'components/tinymce-editor.blade.php: {!! $attributes->get(\'value\') !!}',
    'livewire/jurisdiction/edit-section.blade.php: {!! $newSectionText !!}',
    'livewire/jurisdiction/edit.blade.php: {!! $text !!}',
    'livewire/jurisdiction/shared-content-editor.blade.php: {!! $content !!}',
    'livewire/jurisdiction/shared-content.blade.php: {!! $content !!}',
    'livewire/jurisdiction/show.blade.php: {!! $jurisdiction->display_general_info !!}',
    'livewire/section/edit-section.blade.php: {!! $newSectionText !!}',
    'livewire/settings/two-factor.blade.php: {!! $qrCodeSvg !!}',
];

it('only uses unescaped blade output that has been reviewed', function () {
    $finder = Finder::create()->files()->in(dirname(__DIR__, 2).'/resources/views')->name('*.blade.php');
    $unreviewed = [];

    foreach ($finder as $file) {
        foreach (preg_split('/\R/', $file->getContents()) as $lineNumber => $line) {
            if (! str_contains($line, '{!!')) {
                continue;
            }

            $usage = str_replace(DIRECTORY_SEPARATOR, '/', $file->getRelativePathname()).': '.trim($line);

            if (! in_array($usage, REVIEWED_UNESCAPED_OUTPUT, true)) {
                $unreviewed[] = $file->getRelativePathname().':'.($lineNumber + 1).'  '.trim($line);
            }
        }
    }

    expect($unreviewed)->toBeEmpty(
        "Unreviewed {!! !!} output. Use {{ }} instead, or if the value is sanitized HTML, add it to REVIEWED_UNESCAPED_OUTPUT:\n".implode("\n", $unreviewed)
    );
});
